#!/usr/bin/env bash
# Refreshes Cloudflare's published edge ranges into the two Caddy include files used for the
# trusted client IP (docs/sync/PLAN.md §4.4):
#   cloudflare-trusted.caddy   `trusted_proxies static …`  (global servers block)
#   cloudflare-untrusted.caddy `@untrusted_peer not remote_ip …` (strips a spoofed CF-IPCountry)
# Both also allow {$TRUSTED_PROXIES_EXTRA}: the hop between Cloudflare and Caddy, if any
# (OPEN_QUESTIONS Q8). Run it during release work and commit the result.
set -euo pipefail
cd "$(dirname "$0")"
v4=$(curl -fsS --max-time 20 https://www.cloudflare.com/ips-v4)
v6=$(curl -fsS --max-time 20 https://www.cloudflare.com/ips-v6)
ranges=$(printf '%s\n%s\n' "$v4" "$v6" | tr -d '\r' | sed '/^$/d')
# Every line must be a CIDR; anything else means the download is not what we expect.
if printf '%s\n' "$ranges" | grep -Evq '^[0-9a-fA-F:.]+/[0-9]{1,3}$'; then
  echo "unexpected content in Cloudflare's range lists" >&2
  exit 1
fi
count=$(printf '%s\n' "$ranges" | wc -l)
[ "$count" -ge 10 ] || { echo "only $count ranges; refusing" >&2; exit 1; }
list=$(printf '%s\n' "$ranges" | tr '\n' ' ' | sed 's/ $//')
stamp=$(date -u +%Y-%m-%d)
header="# Generated by update-cloudflare-ips.sh on $stamp from https://www.cloudflare.com/ips-v4 and /ips-v6 ($count ranges)."
printf '%s\ntrusted_proxies static %s {$TRUSTED_PROXIES_EXTRA}\n' "$header" "$list" > cloudflare-trusted.caddy
printf '%s\n@untrusted_peer not remote_ip %s {$TRUSTED_PROXIES_EXTRA}\n' "$header" "$list" > cloudflare-untrusted.caddy
echo "wrote $count ranges ($stamp)"
